<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\Criminal;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class CriminalController extends Controller {public function index(Request $r){$criminals=Criminal::withCount('cases')->when($r->filled('search'),fn($q)=>$q->where(fn($q)=>$q->where('name','like','%'.$r->search.'%')->orWhere('alias','like','%'.$r->search.'%')->orWhere('nid_number','like','%'.$r->search.'%')))->when($r->wanted==='yes',fn($q)=>$q->where('wanted_status',true))->when($r->wanted==='no',fn($q)=>$q->where('wanted_status',false))->latest('criminal_id')->paginate(15)->withQueryString();$summary=(object)['total'=>Criminal::count(),'wanted'=>Criminal::where('wanted_status',true)->count()];return view('admin.criminals',compact('criminals','summary'));}public function edit(Criminal $criminal){return view('admin.criminals',compact('criminal'));}public function update(Request $r,Criminal $criminal){$criminal->update($r->validate(['name'=>'required|string|max:100','alias'=>'nullable|string|max:100','nid_number'=>['nullable','string','max:20',Rule::unique('criminals','nid_number')->ignore($criminal->criminal_id,'criminal_id')],'date_of_birth'=>'nullable|date']));return redirect()->route('admin.criminals.index')->with('success','Criminal record updated.');}public function toggleWanted(Criminal $criminal){$criminal->update(['wanted_status'=>!$criminal->wanted_status]);return back()->with('success','Wanted status updated.');}}
